def render():
 (ROOT/'catalog.json').write_text(json.dumps(CAT,indent=2)+'\n')
 def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows])+'\n'
 def write(name,txt): (ROOT/name).write_text(txt.rstrip()+'\n')
 write('ancestry.md','# Ancestries\n\nHP contributions and base Speed are approved starting fixtures. All traits are\nprovisional. Choose two distinct traits; identical numeric bonuses do not stack.\nCulture is independent of ancestry. Tolkien-inspired flavor is a direction, not\na source of numerical statistics.\n\n'+table(['Ancestry','HP','Speed'],[(n,a['hp'],a['speed']) for n,a in ANCESTRY.items()])+'\n'+'\n'.join('## '+n+'\n\n'+table(['Trait','Benefit'],a['traits']) for n,a in ANCESTRY.items()))
 write('culture-background.md','# Cultures and backgrounds\n\nAll entries provisional. Choose one culture and one background independently of\nancestry; choose one paired option from each row. Each grants the named discipline\nat rank 1 and its paired card. Duplicate rank/card grants each give 1 stage DP.\nNo discipline purchases at level 0.\n\n'+table(['Stage choice','Name','Option A: discipline → card','Option B: discipline → card'],[(kind,n,*[f'{d} → {CARDS[c]["name"]} (`{c}`)' for d,c in options]) for kind,group in [('Culture',CULTURES),('Background',BACKGROUNDS)] for n,options in group.items()]))
 write('class.md','# Classes\n\nAttribute requirements are agreed; both scores must be at least 0 using permanent\ncreation values. Odd has none. HP for Protector/Blade/Arcanist are approved starting\nfixtures; other HP values, discipline options/prices, and signatures are provisional.\nChoose two distinct listed rank-1 disciplines at level 1. Choose one signature\nat each of levels 1, 3, 7; extra class signatures cost the shared tier price.\n\n'+table(['Class','Required attributes','HP','Choose two disciplines'],[(n,', '.join(c['req']) or 'None',c['hp'],', '.join(c['choices'])) for n,c in CLASSES.items()])+'\nSignatures are listed with complete provisional text in [abilities](abilities.md).\nHigher-tier signatures are distinct provisional prototypes, not certified class\nbalance. Review their actual triggers and tactical effects before adoption.\n')
 write('discipline.md','# Disciplines\n\nRanks bought sequentially; no level gates on ranks. Card purchase gates are separate.\nCosts per rank are agreed: Home 1/2/4, Adjacent 2/4/8, Foreign 3/6/12, Opposed 4/8/16.\nThe reduced 12-discipline catalog and each class affinity below are provisional.\nMelee unifies weapon appearance rather than reinstating separate sword/axe skills.\nAll unlisted affinities are Foreign. Odd pays Adjacent for every discipline.\n\n'+table(['Class','Home','Adjacent','Opposed'],[(n,', '.join(c['home']) or '—',', '.join(c['adj']),', '.join(c['opp']) or '—') for n,c in CLASSES.items()])+'\n'+table(['Discipline'],[(d,) for d in DISC]))
 universal='''## Universal reference — Agreed permission, provisional numeric profiles

Everyone receives these references, not DP purchases. No equipment is automatically
granted by a universal card. Costs/ranges below marked provisional where not settled.
All actions repeatable unless constrained by their normal action allowance.

| Card | Cost | Roll / effect |
|---|---|---|
| Basic Melee | Main | Brawn, adjacent, melee weapon, physical 2/3/5 (provisional) |
| Basic Ranged | Main | Agility, range 8, ranged weapon/ammunition, physical 2/3/5 (provisional) |
| Basic Throw | Main | Brawn, range 3, suitable carried item, physical 2/3/5 (provisional); item ends at target square |
| Basic Unarmed | Main | Brawn, adjacent, physical 1/2/4 (provisional) |
| Defend | Maneuver | One Boon to defense rolls until start of your next turn |
| Aid | Maneuver | Adjacent ally, plausible assistance: Boon to next declared action roll before your next turn (provisional timing) |
| Disengage | Maneuver | No movement opportunity attacks this turn |
| Movement | Movement | Move up to Speed; converted Maneuver grants another allowance |
| Shield Block | Reaction | Before eligible defense, shield gives Boon until start of your next turn; DA judges blockability |
| Stabilize | Maneuver | Adjacent Dying PC, no roll, stable at 0, clear death marks |
| Force | Main | Brawn, adjacent physical obstacle/creature: 1/2/3 progress, grapple reduction, or squares of push |

A basic Strong 5 deals 2 against resistance 3, but only 1 against resistance 4+.
This addresses the low-tier armor test, not a universal post-resistance floor of 2.

'''
 txt='# Abilities\n\nAll named purchased/signature cards below are provisional test designs. Tier level\n1/3/7, price 2/4/8; all listed discipline ranks required before purchase. Signature\nrequirements are class + level only. Card types are provisional categories.\n\n'+universal
 for id,c in CARDS.items():
  txt+=f'## {c["name"]} (`{id}`)\n\n- Tier level: {c["level"]}; DP: {c["cost"]}; type: {", ".join(c["types"])}; action: {c["action"]}.\n- Requires: '+(c.get('class_only') or ', '.join(f'{d} {r}' for d,r in c['req'].items()) or 'None')+'. Roll: '+(c['attribute'] or 'None')+'.\n- Acquisition equipment: '+(', '.join(c['gear']) or 'None')+'.\n\n'+c['text']+'\n\n'
 write('abilities.md',txt)
if __name__=='__main__':render();print(f'{len(CARDS)} cards rendered')
